// Synchronous re-implementation of netlify/lib/ncn-gvgs-private/gv2-assets.cjs
// for Cloudflare. The original reads catalogue.json + 3 media files with
// node:fs; here the same files are embedded at build time in
// private-assets.mjs (generated by scripts/build-public.mjs when CF_PAGES=1).
// The logic mirrors the original exactly (same layout lookup, same font
// filtering, same CSS inlining and validation).

import {GV2_ASSETS} from './private-assets.mjs';

export default function loadGV2Assets() {
  const catalogue = JSON.parse(GV2_ASSETS.catalogue);
  const layout = catalogue.layouts.find(item => item.id === 'gv-2');
  const fonts = (catalogue.fontCSS.match(/@font-face\s*\{[^}]*\}/g) || []).filter(rule => rule.includes('ncn-gv2-')).join('\n');
  if (!layout || !fonts) throw new Error('Chưa tải được mẫu Giờ vàng giá sốc 2.');
  const inlineAssets = {
    '/assets/ncn-popup/media/gv2-c58265ed88eabe63.png': 'data:image/png;base64,' + GV2_ASSETS['gv2-c58265ed88eabe63.png'],
    '/assets/ncn-popup/media/gv2-d257d3118827e9d6.woff2': 'data:font/woff2;base64,' + GV2_ASSETS['gv2-d257d3118827e9d6.woff2'],
    '/assets/ncn-popup/media/gv2-940ecfd5ee0f543e.woff2': 'data:font/woff2;base64,' + GV2_ASSETS['gv2-940ecfd5ee0f543e.woff2']
  };
  const css = (fonts + '\n' + layout.css).replace(/url\((['"]?)(\/assets\/ncn-popup\/media\/gv2-[a-z0-9-]+\.(png|woff2))\1\)/g, (_, quote, url) => {
    if (!Object.prototype.hasOwnProperty.call(inlineAssets, url)) throw new Error('Tài nguyên mẫu Giờ vàng giá sốc 2 chưa được đồng bộ.');
    return 'url("' + inlineAssets[url] + '")';
  });
  if (/url\((?!["']?data:)/.test(css) || /<\/style/i.test(css)) throw new Error('Tài nguyên mẫu Giờ vàng giá sốc 2 chưa hợp lệ.');
  return {layout, css};
}
